-- Nom d'un modele par FileID (nil si inconnu). Recherche lineaire dans la chaine : appel rare,
-- mis en cache par l'appelant.
function ns.GetModelName(fileID)
  fileID = tonumber(fileID)
  if not fileID or fileID == 0 then return nil end
  local key = "\n" .. fileID .. " "
  local i = DATA:find(key, 1, true)
  if not i then return nil end
  local e = DATA:find("\n", i + #key, true)
  return DATA:sub(i + #key, (e or 0) - 1)
end

-- Liste { fileId = number, text = nom } triee par nom. Nouvelle table a chaque appel.
function ns.BuildModelList()
  local list = {}
  for id, name in DATA:gmatch("\n(%d+) ([^\n]+)") do
    list[#list + 1] = { fileId = tonumber(id), text = name }
  end
  return list
end
